const items = $input.all();

return items.map(item => {
  // Get the email generated by the AI Agent
  const emailText = item.json.output || "";

  // Separate the subject from the body
  const subjectMatch = emailText.match(/^Subject:\s*(.+)$/im);

  let subject = subjectMatch
    ? subjectMatch[1].trim()
    : "Follow-up from AfriFizz AI Receptionist";

  // Remove the subject line from the email body
  let body = emailText
    .replace(/^Subject:\s*.+\r?\n?/im, "")
    .trim();

  // Remove an optional Markdown code fence if present
  body = body
    .replace(/^```(?:text|markdown)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  return {
    json: {
      subject: subject,
      body: body
    }
  };
});
